      if (open(x - 1, y) && d[i - 1] < 0) { d[i - 1] = di; prev[i - 1] = i; q.push(i - 1); }
      if (open(x, y + 1) && d[i + W] < 0) { d[i + W] = di; prev[i + W] = i; q.push(i + W); }
      if (open(x, y - 1) && d[i - W] < 0) { d[i - W] = di; prev[i - W] = i; q.push(i - W); }
