  if (cap >= INV_MAX) return bad(`가방이 이미 최대 크기(${INV_MAX}칸)입니다`);
  if (ch.gold < bagCost(cap)) return bad(`골드가 부족합니다 (${gStr(bagCost(cap))}G 필요)`);
